<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('catalog_categories.manage');
$id=max(0,(int)($_GET['id']??$_POST['id']??0));$category=null;
if($id){$stmt=db()->prepare('SELECT * FROM service_categories WHERE id=?');$stmt->execute([$id]);$category=$stmt->fetch();if(!$category){http_response_code(404);exit('Categoría no encontrada.');}}
$pageTitle=$category?'Editar categoría':'Nueva categoría';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$description=trim((string)($_POST['description']??''))?:null;$sort=max(0,(int)($_POST['sort_order']??0));$active=isset($_POST['is_active'])?1:0;if($name==='')$errors[]='El nombre es obligatorio.';if(!$errors){$pdo=db();try{$pdo->beginTransaction();if($id){$pdo->prepare('UPDATE service_categories SET name=?,description=?,sort_order=?,is_active=? WHERE id=?')->execute([$name,$description,$sort,$active,$id]);$pdo->prepare('UPDATE service_catalog SET category=? WHERE category_id=?')->execute([$name,$id]);}else{$pdo->prepare('INSERT INTO service_categories(name,description,sort_order,is_active) VALUES (?,?,?,?)')->execute([$name,$description,$sort,$active]);}$pdo->commit();flash('success',$id?'Categoría actualizada.':'Categoría creada.');redirect('service_categories.php');}catch(PDOException$e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='No fue posible guardar. Comprueba que el nombre no esté repetido.';}}}
$v=fn(string$key,mixed$default='')=>$_POST[$key]??($category[$key]??$default);require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2><?=$category?'Actualizar categoría':'Crear categoría reutilizable'?></h2><span class="table-sub">Después podrás asignarla a cualquier producto o servicio del catálogo.</span></div><a class="btn btn-light btn-small" href="service_categories.php">Cancelar</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Nombre *<input name="name" required value="<?=e($v('name'))?>"></label><label>Orden<input type="number" min="0" name="sort_order" value="<?=e($v('sort_order',0))?>"></label><label class="checkbox-row"><input type="checkbox" name="is_active" value="1" <?=((int)$v('is_active',1)===1)?'checked':''?>> Categoría activa</label><label class="full">Descripción<textarea name="description"><?=e($v('description'))?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="service_categories.php">Cancelar</a><button class="btn btn-primary">GUARDAR CATEGORÍA</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
